     "stem": "삼차함수 $f(x)=x^3-3x^2-9x+a$에 대하여 함수 $g(x)$를 $g(x)=|f(x)|$라 하자. 함수 $g(x)$가 $x=\\alpha$, $x=\\beta$ ($\\alpha<\\beta$)에서 극댓값을 가질 때, $|g(\\alpha)-g(\\beta)|>11$을 만족시키는 정수 $a$의 개수는?",
