     "id": "ngd_su2_627224495c",
     "출처": "학교 기출(족보)",
     "해설": "\\(f(x)=x^3-3x^2-9x+a\\)에서 \\(f'(x)=3x^2-6x-9=3(x-3)(x+1)\\)이므로 \\(f\\)는 \\(x=-1\\)에서 극대, \\(x=3\\)에서 극소를 갖는다.\n\\(f(-1)=-1-3+9+a=5+a\\), \\(f(3)=27-27-27+a=a-27\\)이다.\n\\(g(x)=|f(x)|\\)의 극값을 분석하자. 단순근(f가 0을 가로지르는 점)에서는 \\(g\\)가 \\(0\\)에서 꺾이는 극소가 생길 뿐 극대는 생기지 않는다. \\(g\\)의 극대는 오직 \\(f\\)의 극값점에서, 그 극값점에서 \\(|f|\\)가 뾰족한 극대를 형성할 때만 생긴다.\n- \\(x=-1\\): \\(f\\)가 극대이므로, \\(f(-1)>0\\)이면 그 근방에서 \\(f>0\\)이라 \\(g=f\\)가 그대로 극대. \\(f(-1)<0\\)이면 근방에서 \\(f<0\\)이라 \\(g=-f\\)가 극소가 된다. 따라서 \\(x=-1\\)이 \\(g\\)의 극대가 되려면 \\(f(-1)=5+a>0 \\Rightarrow a>-5\\).\n- \\(x=3\\): \\(f\\)가 극소이므로, \\(f(3)<0\\)이면 근방에서 \\(f<0\\)이라 \\(g=-f\\)가 극대. 따라서 \\(x=3\\)이 \\(g\\)의 극대가 되려면 \\(f(3)=a-27<0 \\Rightarrow a<27\\).\n문제에서 \\(g\\)가 두 점 \\(\\alpha<\\beta\\)에서 극대를 가진다고 했으므로 두 조건이 모두 성립해야 한다: \\(-5<a<27\\).\n이때 \\(\\alpha=-1\\), \\(\\beta=3\\)이고,\n\\(g(\\alpha)=f(-1)=5+a\\) (양수이므로), \\(g(\\beta)=-f(3)=27-a\\) (양수이므로).\n\\(|g(\\alpha)-g(\\beta)|=|(5+a)-(27-a)|=|2a-22|=2|a-11|\\).\n조건 \\(2|a-11|>11 \\Rightarrow |a-11|>5.5\\)이므로 \\(a<5.5\\) 또는 \\(a>16.5\\).\n\\(-5<a<27\\)인 정수 \\(a\\)는 \\(-4\\le a\\le 26\\) (총 \\(31\\)개)이다.\n이 중 \\(|a-11|>5.5\\)를 만족하는 정수는:\n- \\(a\\le 5\\) 인 경우: \\(a=-4,\\dots,5\\)로 \\(10\\)개\n- \\(a\\ge 17\\) 인 경우: \\(a=17,\\dots,26\\)로 \\(10\\)개\n따라서 총 \\(10+10=20\\)개이다.\n따라서 정답은 ④ 이다."
