     "해설": "\\(\\displaystyle f(x)=\\frac{ax+b}{2x+c}=\\frac{a}{2}+\\frac{2b-ac}{2(2x+c)}\\)로 변형된다. \\(x>0\\)에서 \\(c\\ge0\\)이면 \\(2x+c>0\\)이 항상 성립하여 정의역 전체에서 함수가 잘 정의된다. \\(2b-ac\\ne0\\)이면 둘째 항이 \\(x\\)에 대해 일대일(단조)이므로 \\(f\\)도 일대일이고, \\(2b=ac\\)이면 \\(f\\)가 상수함수가 되어 일대일이 아니다. 따라서 조건은 \\(2b\\ne ac\\), \\(a,b,c\\in\\{0,1,\\dots,9\\}\\)이다. \\(2b=ac\\)를 만족하는 \\((a,c)\\) 쌍을 세면: \\(a=0\\)일 때 10개, \\(a=1\\): 5개, \\(a=2\\): 10개, \\(a=3\\): 4개, \\(a=4\\): 5개, \\(a=5\\): 2개, \\(a=6\\): 4개, \\(a=7\\): 2개, \\(a=8\\): 3개, \\(a=9\\): 2개로 합이 47개이며, 각 쌍마다 \\(b\\)가 하나씩 정해진다. 전체 \\(10^3=1000\\)개에서 47개를 제외하면 \\(1000-47=953\\)."
