     "해설": "\\(\\displaystyle f(x)=\\dfrac{ax+b}{x+c}=a+\\dfrac{b-ac}{x+c}\\)이고 \\(c\\ge1\\)이므로 \\(x>0\\)에서 \\(x+c>0\\)이라 분모가 0이 되는 문제는 없다. 이 함수가 일대일이 아닌 경우는 \\(b-ac=0\\)일 때, 즉 \\(f(x)\\equiv a\\)인 상수함수가 되는 경우뿐이다. \\(a,b,c\\in\\{1,\\dots,9\\}\\) 전체 경우의 수는 \\(9^3=729\\)이고, \\(b=ac\\le9\\)를 만족하는 \\((a,c)\\) 쌍의 개수를 세면 \\(a=1\\)일 때 9개, \\(a=2\\)일 때 4개, \\(a=3\\)일 때 3개, \\(a=4\\)일 때 2개, \\(a=5,\\dots,9\\)일 때 각각 1개로 총 \\(9+4+3+2+1\\times5=23\\)개이다. 따라서 일대일함수가 되는 순서쌍의 개수는 \\(729-23=706\\)이다."
