     "해설": "\\(f(x) = x^3 - 3mx + m - 3\\) 라 하자.\n\\(f'(x) = 3x^2 - 3m = 3(x^2 - m)\\)\n삼차방정식이 서로 다른 두 실근을 가지려면, \\(f(x)\\)가 극값을 가지면서(즉 \\(m>0\\)) 극대값과 극소값 중 하나가 \\(0\\)이어야 한다 (한 근이 중근, 다른 하나가 단순근).\n\\(m>0\\)일 때 극점은 \\(x = \\pm\\sqrt{m}\\) 이다.\n\\(f(\\sqrt{m}) = m\\sqrt{m} - 3m\\sqrt{m} + m - 3 = -2m\\sqrt{m} + m - 3\\) (극소값)\n\\(f(-\\sqrt{m}) = -m\\sqrt{m} + 3m\\sqrt{m} + m - 3 = 2m\\sqrt{m} + m - 3\\) (극대값)\n두 값의 곱이 \\(0\\)이어야 하므로\n\\(\\left(m-3\\right)^2 - \\left(2m\\sqrt{m}\\right)^2 = 0\\)\n\\(\\left(m-3\\right)^2 - 4m^3 = 0\\)\n\\(4m^3 - m^2 + 6m - 9 = 0\\)\n선지의 값을 대입해보면 \\(m=1\\)일 때\n\\(4(1) - 1 + 6 - 9 = 0\\)\n이 성립한다.\n검증: \\(m=1\\)이면 \\(f(x) = x^3 - 3x - 2\\) 이고, 이를 인수분해하면\n\\(f(x) = (x+1)^2(x-2)\\)\n이므로 방정식 \\(x^3 - 3x - 2 = 0\\)의 근은 \\(x=-1\\) (중근), \\(x=2\\) 로 서로 다른 두 실근을 갖는다.\n따라서 정답은 ② 이다."
