     "stem": "함수 $f(x)=\\begin{cases} 1&(x<0) \\\\ 0&(x=0) \\\\ -1&(x>0) \\end{cases}$ $g(x)=\\begin{cases}x^2&(x \\neq 0) \\\\1&(x=0)\\end{cases}$에 대하여 <보기>에서 옳은 것만을 있는 대로 고른 것은?\\n\\n<보기>\\nㄱ. $\\lim\\limits _{x \\to 0} {g(f(x))}=1$\\nㄴ. $\\lim\\limits _{x \\to 0} {f(g(x))}=-1$\\nㄷ. $f(\\lim\\limits _{x \\to 0} {g(x)})$의 값은 존재하지 않는다.",
