     "해설": "ㄱ. \\(x \\to 0^-\\)일 때 \\(f(x)=1\\)이므로 \\(g(f(x))=g(1)=1^2=1\\)이고, \\(x \\to 0^+\\)일 때 \\(f(x)=-1\\)이므로 \\(g(f(x))=g(-1)=(-1)^2=1\\)이다. 좌우극한이 모두 \\(1\\)이므로 \\(\\lim\\limits_{x \\to 0} g(f(x))=1\\)이다. (참)\nㄴ. \\(x \\neq 0\\)일 때 \\(g(x)=x^2\\)이고 \\(x \\to 0\\)이면 \\(x \\neq 0\\)이므로 \\(g(x)=x^2>0\\)이며 \\(0\\)에 한없이 가까워진다. 즉 \\(g(x)\\)는 양수이면서 \\(0\\)으로 수렴하므로, 이때 \\(f(g(x))=f(\\text{양수})=-1\\)이다. 좌우 모두 \\(-1\\)이므로 \\(\\lim\\limits_{x \\to 0} f(g(x))=-1\\)이다. (참)\nㄷ. \\(\\lim\\limits_{x \\to 0} g(x)\\)를 구할 때는 \\(x=0\\) 에서의 함숫값 \\(g(0)=1\\)과 무관하게 \\(x \\neq 0\\)인 근방에서의 극한을 구한다. \\(x \\neq 0\\)이면 \\(g(x)=x^2 \\to 0\\)이므로 \\(\\lim\\limits_{x \\to 0} g(x)=0\\)이다. 따라서 \\(f(\\lim\\limits_{x \\to 0} g(x))=f(0)\\)인데, \\(f(0)=0\\)으로 정의되어 있으므로 \\(f(\\lim\\limits_{x \\to 0} g(x))=0\\)으로 값이 존재한다. 따라서 \"값이 존재하지 않는다\"는 ㄷ은 거짓이다.\n따라서 ㄱ, ㄴ만 옳으므로 정답은 ② 이다."
