     "해설": "직선 \\(y = kx + 2k = k(x+2)\\)는 \\(k\\)의 값에 관계없이 항상 점 \\((-2,\\, 0)\\)을 지난다.\n함수 \\(y = -\\sqrt{x+1}+2\\)의 정의역은 \\(x \\geq -1\\)이고, 시작점은 \\((-1,\\, 2)\\)이다.\n두 그래프의 교점 조건: \\(x \\geq -1\\)에서 \\(k(x+2) = -\\sqrt{x+1}+2\\)를 만족하는 실수 \\(x\\)가 존재해야 한다.\n\\(t = \\sqrt{x+1} \\geq 0\\)으로 치환하면 \\(x = t^2-1\\), \\(x+2 = t^2+1\\)이므로\n\\[k(t^2+1) = -t+2 \\implies k = \\frac{2-t}{t^2+1} =: f(t)\\]\n\\(f(t)\\)의 치역을 구하기 위해 미분한다.\n\\[f'(t) = \\frac{(-1)(t^2+1) - (2-t)(2t)}{(t^2+1)^2} = \\frac{t^2-4t-1}{(t^2+1)^2}\\]\n\\(f'(t) = 0\\): \\(t^2-4t-1=0 \\implies t = 2+\\sqrt{5}\\) (\\(t \\geq 0\\)이므로 양근 채택)\n- \\(t \\in [0,\\, 2+\\sqrt{5})\\): 감소, \\(t \\in (2+\\sqrt{5},\\, \\infty)\\): 증가\n극솟값(최솟값):\n\\[f(2+\\sqrt{5}) = \\frac{-\\sqrt{5}}{(2+\\sqrt{5})^2+1} = \\frac{-\\sqrt{5}}{10+4\\sqrt{5}} = \\frac{-\\sqrt{5}(5-2\\sqrt{5})}{2 \\cdot 5} = 1 - \\frac{\\sqrt{5}}{2}\\]\n수치: \\(\\displaystyle 1 - \\frac{\\sqrt{5}}{2} \\approx 1 - 1.118 = -0.118\\)\n경계값: \\(f(0) = 2\\), \\(\\displaystyle\\lim\\limits_{t \\to \\infty} f(t) = 0^-\\)\n따라서 \\(f(t)\\)의 치역은 \\(\\displaystyle \\left[1-\\dfrac{\\sqrt{5}}{2},\\; 2\\right] \\approx [-0.118,\\; 2]\\)이다.\n교점이 존재하려면 \\(\\displaystyle k \\in \\left[1-\\dfrac{\\sqrt{5}}{2},\\; 2\\right]\\)이어야 한다.\n이 범위에 속하는 정수 \\(k\\): \\(0,\\; 1,\\; 2\\) → 총 \\(3\\)개\n검증:\n- \\(k=2\\): \\(t=0\\)(\\(x=-1\\))에서 교점 \\((-1,\\,2)\\) ✓\n- \\(k=1\\): \\(\\sqrt{x+1}=-x\\)에서 \\(\\displaystyle x=\\frac{1-\\sqrt{5}}{2}\\in[-1,0]\\) ✓\n- \\(k=0\\): \\(y=0\\)에서 \\(x=3\\) ✓\n- \\(k=-1\\): \\(x^2+7x+15=0\\), 판별식 \\({}<0\\) → 교점 없음 ✓\n따라서 정답은 ③ 이다."
