     "stem": "최고차항의 계수가 양수인 두 다항식 $f(x), g(x)$가 다음 조건을 만족시킨다. (가) $f(x)$를 $x^2+g(x)$로 나눈 몫은 $x+3$이고 나머지는 $\\{g(x)\\}^2-x^2$이다. (나) $f(x)$는 $g(x)$로 나누어 떨어진다. $f(0)\\neq 0$일 때, $f(-1)$의 값은?",
