     "해설": "미분가능 조건에서 \\(f(1)=3,\\ f'(1)=0\\)이다. \\(f'(x)=3(x-a)(x-1)\\) (\\(a<1\\)) 꼴로 \\(x=a\\)에서의 국소최댓값이 전체 최댓값 \\(35\\)가 된다. 적분하여 \\(f(1)=3,\\ f(a)=35\\)를 연립하면 \\(a=-3\\), \\(f(x)=x^3+3x^2-9x+8\\)을 얻는다. \\(g(-2)=f(-2)=-8+12+18+8=30\\)이므로 답은 ②"
