     "id": "var_tbg_040_20261110_1",
     "해설": "\\(\\displaystyle f(x)=\\dfrac{2x+1}{x+a}\\)는 행렬 \\(\\begin{pmatrix}2&1\\\\1&a\\end{pmatrix}\\)로 나타낼 수 있는 일차변환이고, \\((f\\circ f)(x)=x\\)가 항상 성립하려면 \\(f\\)가 자기 자신의 역함수(대합)여야 한다. 이는 행렬의 대각합이 \\(0\\)일 조건, 즉 \\(2+a=0\\)과 같다. 따라서 \\(a=-2\\)이고 이는 \\(\\displaystyle a\\ne\\frac12\\) 조건도 만족하므로 답은 ①"
