     "id": "var_tb_c047964905_20260801_2",
     "해설": "\\(f(x)=ax+b\\)라 하면 \\(f=f^{-1}\\)이므로 \\(f(f(x))=x\\)이고, 이를 전개하면 \\(a^2=1\\)과 \\(b(a+1)=0\\)이 성립한다. \\(a=1\\)이면 \\(b=0\\)이어야 하는데 \\(f(2)=2\\ne 5\\)이므로 모순이고, 따라서 \\(a=-1\\)이다. \\(f(x)=-x+b\\)에 \\(f(2)=5\\)를 대입하면 \\(-2+b=5\\)이므로 \\(b=7\\), 즉 \\(f(x)=-x+7\\)이다. \\(x\\)절편은 \\(-x+7=0\\)에서 \\(m=7\\), \\(y\\)절편은 \\(f(0)=7\\)에서 \\(n=7\\)이므로 \\(m+n=14\\)이다."
