     "출처": "신흥고 기출 2020",
     "해설": "\\(f\\)가 일대일 대응이 되려면 전체 함수가 순증가 또는 순감소해야 한다.\n\\(x = 0\\)에서 좌극한: \\(\\lim\\limits_{x \\to 0^-} f(x) = 1\\), \\(f(0) = 1\\)이므로 두 구간은 \\(x = 0\\)에서 이어진다.\n경우 1: 두 구간 모두 증가 (\\(a+1 > 0\\) 이고 \\(3-a > 0\\))\n\\(x < 0\\) 구간의 치역은 \\((-\\infty,\\, 1)\\), \\(x \\geq 0\\) 구간의 치역은 \\([1,\\, +\\infty)\\)이므로 치역이 겹치지 않아 전사이자 단사가 성립한다.\n조건: \\(a > -1\\) 이고 \\(a < 3\\) → \\(-1 < a < 3\\)\n이 범위의 자연수: \\(a = 1,\\, 2\\) (2개)\n경우 2: 두 구간 모두 감소 (\\(a+1 < 0\\) 이고 \\(3-a < 0\\))\n\\(a < -1\\) 이고 \\(a > 3\\)을 동시에 만족하는 수는 존재하지 않는다.\n경우 3: 한 구간만 단조 → 두 구간의 치역이 겹쳐 일대일 불성립.\n따라서 자연수 \\(a\\)는 \\(1, 2\\)로 총 2개이다.\n따라서 정답은 ③ 이다."
