     "출처": "신목고 기출 2020",
     "해설": "\\(f\\)가 일대일대응이 되려면 정의역 전체에서 순증가 또는 순감소해야 한다.\n\\(x=0\\)에서 연속성 확인: 왼쪽 극한 \\((4-a)(0)+2=2\\), \\(f(0)=(a-1)(0)+2=2\\)이므로 항상 연속이다.\n경우 1 (순증가): 두 기울기 모두 양수\n\\[a-1>0 \\quad \\Rightarrow \\quad a>1\\]\n\\[4-a>0 \\quad \\Rightarrow \\quad a<4\\]\n따라서 \\(1<a<4\\), 정수값: \\(a\\in\\{2,3\\}\\)\n경우 2 (순감소): \\(a-1<0\\)이고 \\(4-a<0\\) 동시 만족 불가 (모순).\n정수 \\(a\\)의 값의 합: \\(2+3=5\\)\n따라서 정답은 ② 이다."
