     "출처": "이산고 기출 2020",
     "해설": "\\(X = \\{-1, 0, 1\\}\\)에서 \\(Y = \\{0, 1, 2\\}\\)로의 일대일대응이 되려면 각 원소가 서로 다른 값으로 대응되고, 공역과 치역이 일치해야 한다.\n각 선지를 \\(X\\)의 원소에 대입한다.\n① \\(y = x\\): \\(f(-1) = -1 \\notin Y\\) → 불가\n② \\(y = x^2\\): \\(f(-1) = 1, f(0) = 0, f(1) = 1\\) → \\(f(-1) = f(1)\\)이므로 일대일 아님 → 불가\n③ \\(y = x^3 - 1\\): \\(f(-1) = -2 \\notin Y\\) → 불가\n④ \\(y = |x|\\): \\(f(-1) = 1, f(0) = 0, f(1) = 1\\) → \\(f(-1) = f(1)\\)이므로 일대일 아님 → 불가\n⑤ \\(y = |x+1|\\):\n\\[f(-1) = |-1+1| = 0, \\quad f(0) = |0+1| = 1, \\quad f(1) = |1+1| = 2\\]\n치역 \\({}= \\{0, 1, 2\\} = Y\\)이고 모두 서로 다르므로 일대일대응이다.\n따라서 정답은 ⑤ 이다."
