     "해설": "\\(s=x+y,\\ d=x-y\\)라 하면 \\(\\displaystyle xy=\\dfrac{s^2-d^2}{4}=\\dfrac{3}{4}\\)에서 \\(s^2=d^2+3\\).\n목적식은 \\(\\displaystyle f=\\dfrac{s^4}{d^2+1}=\\dfrac{(d^2+3)^2}{d^2+1}\\)이다.\n\\(t=d^2\\ (t>0,\\ x\\neq y\\)이므로 \\(d\\neq0)\\), \\(u=t+1>1\\)로 치환하면\n\\[f=\\frac{(u+2)^2}{u}=u+4+\\frac{4}{u}.\\]\n산술-기하평균에 의해 \\(\\displaystyle u+\\dfrac{4}{u}\\ge 2\\sqrt{4}=4\\)이고 등호는 \\(u=2\\)일 때 성립한다. \\(u=2>1\\)이므로 실현 가능하며,\n\\[f_{\\min}=4+4=8=m.\\]\n\\(u=2\\)이면 \\(t=d^2=1\\)이고 \\(s^2=t+3=4\\)이므로 \\(s=x+y=\\pm2\\).\n즉 최솟값 \\(m=8\\)을 만족하는 \\((x,y)\\)들에 대해 \\(x+y\\)의 가능한 값은 \\(\\pm2\\)이며, 이 값들이 바로 \\(\\displaystyle m=\\dfrac{(a+b)^4}{(a-b)^2+1}\\)을 만족하는 \\((a,b)\\)의 \\(a+b\\) 값이 된다.\n따라서 \\(a+b\\)의 최댓값 \\(M=2\\)이고,\n\\[m+M=8+2=10.\\]\n따라서 정답은 ⑤ 이다."
